=back

=head2 Google::Cloud::Discoveryengine::V1beta::SearchService::SearchResponse

Response message for
[SearchService.Search][google.cloud.discoveryengine.v1beta.SearchService.Search]
method.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->results() >> / C<< $msg->results($value) >>

Type: C<Message> (L<Google::Cloud::Discoveryengine::V1beta::SearchService::SearchResponse::SearchResult>)

A list of matched documents. The order represents the ranking.

=item * C<< $msg->facets() >> / C<< $msg->facets($value) >>

Type: C<Message> (L<Google::Cloud::Discoveryengine::V1beta::SearchService::SearchResponse::Facet>)

Results of facets requested by user.

=item * C<< $msg->guided_search_result() >> / C<< $msg->guided_search_result($value) >>

Type: C<Message> (L<Google::Cloud::Discoveryengine::V1beta::SearchService::SearchResponse::GuidedSearchResult>)

Guided search result.

=item * C<< $msg->total_size() >> / C<< $msg->total_size($value) >>

Type: C<Int32>

The estimated total count of matched items irrespective of pagination. The
count of
[results][google.cloud.discoveryengine.v1beta.SearchResponse.results]
returned by pagination may be less than the
[total_size][google.cloud.discoveryengine.v1beta.SearchResponse.total_size]
that matches.

=item * C<< $msg->attribution_token() >> / C<< $msg->attribution_token($value) >>

Type: C<String>

A unique search token. This should be included in the
[UserEvent][google.cloud.discoveryengine.v1beta.UserEvent] logs resulting
from this search, which enables accurate attribution of search model
performance. This also helps to identify a request during the customer
support scenarios.

=item * C<< $msg->redirect_uri() >> / C<< $msg->redirect_uri($value) >>

Type: C<String>

The URI of a customer-defined redirect page. If redirect action is
triggered, no search is performed, and only
[redirect_uri][google.cloud.discoveryengine.v1beta.SearchResponse.redirect_uri]
and
[attribution_token][google.cloud.discoveryengine.v1beta.SearchResponse.attribution_token]
are set in the response.

=item * C<< $msg->next_page_token() >> / C<< $msg->next_page_token($value) >>

Type: C<String>

A token that can be sent as
[SearchRequest.page_token][google.cloud.discoveryengine.v1beta.SearchRequest.page_token]
to retrieve the next page. If this field is omitted, there are no
subsequent pages.

=item * C<< $msg->corrected_query() >> / C<< $msg->corrected_query($value) >>

Type: C<String>

Contains the spell corrected query, if found. If the spell correction type
is AUTOMATIC, then the search results are based on corrected_query.
Otherwise the original query is used for search.

=item * C<< $msg->suggested_query() >> / C<< $msg->suggested_query($value) >>

Type: C<String>

Corrected query with low confidence, AKA did you mean query.
Compared with corrected_query, this field is set when SpellCorrector
returned a response, but FPR(full page replacement) is not triggered
because the corrction is of low confidence(eg, reversed because there are
matches of the original query in document corpus).

=item * C<< $msg->summary() >> / C<< $msg->summary($value) >>

Type: C<Message> (L<Google::Cloud::Discoveryengine::V1beta::SearchService::SearchResponse::Summary>)

A summary as part of the search results.
This field is only returned if
[SearchRequest.ContentSearchSpec.summary_spec][google.cloud.discoveryengine.v1beta.SearchRequest.ContentSearchSpec.summary_spec]
is set.

=item * C<< $msg->applied_controls() >> / C<< $msg->applied_controls($value) >>

Type: C<String>

Controls applied as part of the Control service.

=item * C<< $msg->geo_search_debug_info() >> / C<< $msg->geo_search_debug_info($value) >>

Type: C<Message> (L<Google::Cloud::Discoveryengine::V1beta::SearchService::SearchResponse::GeoSearchDebugInfo>)

=item * C<< $msg->query_expansion_info() >> / C<< $msg->query_expansion_info($value) >>

Type: C<Message> (L<Google::Cloud::Discoveryengine::V1beta::SearchService::SearchResponse::QueryExpansionInfo>)

Query expansion information for the returned results.

=item * C<< $msg->natural_language_query_understanding_info() >> / C<< $msg->natural_language_query_understanding_info($value) >>

Type: C<Message> (L<Google::Cloud::Discoveryengine::V1beta::SearchService::SearchResponse::NaturalLanguageQueryUnderstandingInfo>)

Output only. Natural language query understanding information for the
returned results.

=item * C<< $msg->session_info() >> / C<< $msg->session_info($value) >>

Type: C<Message> (L<Google::Cloud::Discoveryengine::V1beta::SearchService::SearchResponse::SessionInfo>)

Session information.

Only set if
[SearchRequest.session][google.cloud.discoveryengine.v1beta.SearchRequest.session]
is provided. See its description for more details.

=item * C<< $msg->one_box_results() >> / C<< $msg->one_box_results($value) >>

Type: C<Message> (L<Google::Cloud::Discoveryengine::V1beta::SearchService::SearchResponse::OneBoxResult>)

A list of One Box results. There can be multiple One Box results of
different types.

=item * C<< $msg->search_link_promotions() >> / C<< $msg->search_link_promotions($value) >>

Type: C<Message> (L<Google::Cloud::Discoveryengine::V1beta::Common::SearchLinkPromotion>)

Promotions for site search.

=item * C<< $msg->semantic_state() >> / C<< $msg->semantic_state($value) >>

Type: C<Enum> (L<Google::Cloud::Discoveryengine::V1beta::SearchResponse::SemanticState>)

Output only. Indicates the semantic state of the search response.

